    { id = "ps-teld-141", ["do"] = "accept", quest = 2561, npc = 7317, at = {1438, 44.94, 61.59}, z = 1280.4, chain = "ps-teld-s042-7317", text = "Coge la misión de Rageclaw.", status = "unverified", reqlevel = 3 },
    { id = "ps-teld-142", ["do"] = "complete", quest = 2561, obj = 1, at = {1438, 45.53, 58.58}, z = 1257.3, text = "Mata {npc:7318} (1) para «{quest:2561}».", tip = "[EN] {npc:7318}, in the den; walks around Ban'ethil Hollow: look inside the circle on the map. Usa {item:8149} para «{quest:2561}».", status = "unverified" },
    { id = "ps-teld-143", ["do"] = "turnin", quest = 2561, npc = 7317, at = {1438, 44.94, 61.59}, z = 1280.4, text = "Vuelve con Oben y entrega.", status = "unverified" },
    { id = "ps-teld-144", ["do"] = "accept", quest = 99053, npc = 275744, at = {1438, 44.68, 58.92}, escort = true, text = "En el túmulo, habla con la Centinela Lynessa Duskblossom y acepta su escolta (nueva de Forever).", tip = "Haz antes las reliquias y los amuletos: la escolta acaba fuera y no tendrás que volver a entrar.", status = "unverified", reqlevel = 4 },
    { id = "ps-teld-145", ["do"] = "goto", at = {1438, 46.4, 57.3}, text = "Ve a Ban'ethil Hollow, fuera del túmulo.", tip = "Saca a Lynessa y mantenla con vida.", status = "unverified" },
    { id = "ps-teld-146", ["do"] = "complete", quest = 99053, escort = true, text = "Escolta a Lynessa hasta la salida del túmulo.", status = "unverified" },
    { id = "ps-teld-147", ["do"] = "complete", quest = 933, obj = 1, at = {1438, 42.4, 67.1}, text = "Usa {item:5621} para «{quest:933}».", tip = "Al suroeste del túmulo. El pozo de la luna está junto a las charcas. Recoge {item:5645} (1) de {obj:19551} para «{quest:933}». Usa la {item:5621} en el pozo de la luna.", status = "unverified" },
    { id = "ps-teld-148", ["do"] = "accept", quest = 930, at = {1438, 42.61, 76.19}, z = 1303.6, text = "Al sur de las pozas, examina la planta de frutos extraños: misión para Denalan.", tip = "[EN] South of the pools. The {obj:6751} grows by the Hold; the furbolgs around it drop the rest of the fangs.", status = "unverified", reqlevel = 4 },
    { id = "ps-teld-149", ["do"] = "complete", quest = 490, obj = 1, at = {1438, 41.3, 77.01}, wps = {{1438, 38.8, 80.0, "Colmillo Tuercepinos"}, {1438, 41.4, 72.8, "Colmillo Tuercepinos"}, {1438, 38.3, 66.7, "Colmillo Tuercepinos"}}, text = "Consigue {item:5220} (15) para «{quest:490}».", tip = "[EN] {item:5220}: any Gnarlpine furbolg.", status = "unverified" },
    { id = "ps-teld-150", ["do"] = "turnin", quest = 487, npc = 2151, at = {1438, 52.91, 57.2}, text = "De vuelta hacia Dolanaar, entrega los emboscadores a Amara.", tip = "{npc:2151} patrulla el camino al oeste de la aldea: si no está en la flecha, sigue el camino hasta encontrarla.", status = "unverified" },
    { id = "ps-teld-151", ["do"] = "turnin", quest = 932, npc = 3567, at = {1438, 55.57, 56.95}, z = 1354.9, text = "Entrega la cabeza de Melenas a Tallonkai.", tip = "[EN] {npc:3567}, upstairs.", status = "unverified" },
    { id = "ps-teld-152", ["do"] = "turnin", quest = 483, npc = 2078, at = {1438, 55.96, 57.27}, z = 1313.9, chain = "ps-teld-s046-2078", text = "Entrega las reliquias a Athridas.", status = "unverified" },
    { id = "ps-teld-153", ["do"] = "accept", quest = 486, npc = 2078, at = {1438, 55.96, 57.27}, z = 1313.9, chain = "ps-teld-s046-2078", text = "Coge la misión de Ursal el Triturador: hazla al 12 o sáltatela.", status = "unverified", reqlevel = 4 },
    { id = "ps-teld-154", ["do"] = "turnin", quest = 99053, npc = 2081, at = {1438, 56.0, 59.52}, z = 1308.9, text = "En Dolanaar, entrega la escolta a la Centinela Kyra Starsong.", status = "unverified" },
    { id = "ps-teld-155", ["do"] = "turnin", quest = 933, npc = 3515, at = {1438, 56.14, 61.71}, z = 1294.2, chain = "ps-teld-s046-3515", text = "Entrega la redoma de turmalina a Corithras.", status = "unverified" },
    { id = "ps-teld-156", ["do"] = "accept", quest = 7383, npc = 3515, at = {1438, 56.14, 61.71}, z = 1294.2, chain = "ps-teld-s046-3515", text = "Coge la siguiente Corona de la Tierra: poza del Claro del Oráculo.", status = "unverified" },
    { id = "ps-teld-157", ["do"] = "complete", quest = 489, obj = 1, at = {1438, 61.6, 53.4}, z = 1323.0, text = "Recoge {item:3418} (3) de {obj:1673} para «{quest:489}».", tip = "[EN] Fel Cones lie under the trees all around Dolanaar and {npc:2150}: pick them up on the road east and hand them to {npc:2150} on the way to {npc:7234}.", status = "unverified" },
    { id = "ps-teld-158", ["do"] = "turnin", quest = 489, npc = 2150, at = {1438, 60.35, 56.16}, text = "Vuelve a Dolanaar y entrega los conos a Zenn.", status = "unverified" },
    { id = "ps-teld-159", ["do"] = "complete", quest = 2459, obj = 1, at = {1438, 68.27, 52.18}, z = 1324.4, text = "Mata {npc:7235} (7) para «{quest:2459}».", tip = "Ferocitas lleva místicos con él: llévalos de uno en uno. Si hay cola, sáltatela. [EN] Gnarlpine Mystics and {npc:7234} camp north-east of Villa Brisa Estelar. {npc:7234} drops the {item:8049}: open it for the jewel.\nCareful: {npc:7234} waits near the camp fire with mystics around him, so pulling him without adds is hard.", status = "unverified" },
    { id = "ps-teld-160", ["do"] = "loot", item = 8049, count = 1, at = {1438, 69.37, 53.41}, text = "Consigue {item:8049} de {npc:7234}.", tip = "[EN] {item:8049}, from {npc:7234}.", status = "unverified" },
    { id = "ps-teld-161", ["do"] = "complete", quest = 2459, obj = 2, at = {1438, 69.4, 53.4}, text = "Consigue {item:8050} (1) para «{quest:2459}».", status = "unverified" },
    { id = "ps-teld-162", ["do"] = "turnin", quest = 2459, npc = 3567, at = {1438, 55.57, 56.95}, z = 1354.9, chain = "ps-teld-s049-3567", text = "Vuelve a Dolanaar y entrega a Tallonkai.", tip = "[EN] The road west to the Claro del Oráculo runs through Dolanaar: hand {npc:3567} the jewel on the way. [EN] {npc:3567}, upstairs.", status = "unverified" },
    { id = "ps-teld-163", ["do"] = "accept", quest = 98403, npc = 3567, at = {1438, 55.57, 56.95}, z = 1354.9, optional = true, chain = "ps-teld-s049-3567", text = "Coge la continuación (nueva de Forever): arañas corruptas y musgo vil al norte. Hazla al 10-11.", status = "unverified", reqlevel = 4 },
    { id = "ps-teld-164", ["do"] = "complete", quest = 98403, obj = 1, at = {1438, 49.72, 52.97}, wps = {{1438, 48.9, 49.7, "Befouled Webwood"}, {1438, 47.2, 49.7, "Befouled Webwood"}, {1438, 49.5, 46.1, "Befouled Webwood"}}, optional = true, text = "Mata {npc:272096} (8) para «{quest:98403}».", tip = "Al noroeste de Dolanaar, camino del Claro del Oráculo, los Tejemadera infectos merodean por el bosque; {npc:272116} ronda por su borde este y lleva el {item:281023}.\n{npc:272116} es élite (nivel 12): se recomienda ir en grupo. Despeja primero las arañas a su alrededor y atráelo a él solo.", status = "unverified" },
    { id = "ps-teld-165", ["do"] = "complete", quest = 98403, obj = 2, at = {1438, 51.37, 45.5}, wps = {{1438, 51.3, 43.8, "Musgovil maduro"}}, optional = true, text = "Consigue {item:281023} (1) de {npc:272116} para «{quest:98403}».", tip = "Élite: mejor en grupo.", status = "unverified" },
    { id = "ps-teld-166", ["do"] = "complete", quest = 923, obj = 1, at = {1438, 43.91, 42.69}, z = 1292.3, wps = {{1438, 42.3, 41.7, "Tumor musgoso"}, {1438, 43.8, 40.0, "Tumor musgoso"}, {1438, 42.2, 37.8, "Tumor musgoso"}}, text = "Consigue {item:5170} (5) de {npc:2027} y {npc:2029} y {npc:2030} para «{quest:923}».", tip = "Al oeste desde las arañas hasta el Wellspring River y luego al norte por su curso hasta el claro: los brezomaderas de sus orillas sueltan los tumores musgosos. [EN] {item:5170}: timberlings.", status = "unverified" },
    { id = "ps-teld-167", ["do"] = "accept", quest = 937, npc = 3519, at = {1438, 38.32, 34.36}, z = 1324.5, text = "Coge la misión de la Centinela Arynia Cloudsbreak, junto a la poza.", tip = "El pozo de la luna está en el centro del claro. La {obj:6752} crece en su extremo norte.", status = "unverified", reqlevel = 6 },
    { id = "ps-teld-168", ["do"] = "complete", quest = 7383, obj = 1, at = {1438, 38.4, 34.1}, text = "Usa {item:18152} para «{quest:7383}».", tip = "Recoge {item:18151} (1) de {obj:19552} para «{quest:7383}». Usa la {item:18152} en el pozo de la luna.", status = "unverified" },
    { id = "ps-teld-169", ["do"] = "turnin", quest = 99046, npc = 275683, at = {1438, 37.54, 36.81}, chain = "ps-teld-s052-275683", text = "Sal de Darnassus y sube al norte, al Claro del Oráculo. Entrega a la Centinela Eralya Leafshadow.", status = "unverified" },
    { id = "ps-teld-170", ["do"] = "accept", quest = 99047, npc = 275683, at = {1438, 37.54, 36.81}, chain = "ps-teld-s052-275683", text = "Coge su misión: vuelve con Byancie a Dolanaar.", status = "unverified", reqlevel = 4 },
    { id = "ps-teld-171", ["do"] = "complete", quest = 937, obj = 1, at = {1438, 37.32, 37.79}, z = 1318.9, wps = {{1438, 35.6, 38.0, "Cinturón Sangrepluma"}, {1438, 34.5, 35.0, "Cinturón Sangrepluma"}, {1438, 32.2, 32.3, "Cinturón Sangrepluma"}}, text = "Consigue {item:5204} (6) para «{quest:937}».", tip = "[EN] The Bloodfeather harpies nest on the slopes west and north of the glade. «{quest:938}», an injured sabercat, lies by the glade's west wall among them: lead her back to Sentinel Arynia at the moonwell before her time runs out.\nCareful: The harpies stand packed together, so extra ones often join a fight. Casters are mixed in among them.", status = "unverified" },
    { id = "ps-teld-172", ["do"] = "accept", quest = 938, npc = 3568, at = {1438, 31.54, 31.61}, z = 1331.6, escort = true, text = "Al oeste del claro, habla con Mist, la cría de sable, y empieza la escolta.", tip = "[EN] «{quest:938}», by the west wall. Misión con tiempo: 9 min desde que la coges.", status = "unverified", reqlevel = 7 },
    { id = "ps-teld-173", ["do"] = "complete", quest = 938, at = {1438, 38.3, 34.4}, escort = true, text = "Lleva a Mist hasta Arynia sin perderla.", tip = "Ve despacio y no tires grupos: si Mist muere hay que volver a por ella.", status = "unverified" },
    { id = "ps-teld-174", ["do"] = "turnin", quest = 937, npc = 3519, at = {1438, 38.32, 34.36}, z = 1324.5, chain = "ps-teld-s054-3519", text = "Entrega los cinturones a Arynia.", tip = "Vuelve al pozo de la luna.", status = "unverified" },
    { id = "ps-teld-175", ["do"] = "turnin", quest = 938, npc = 3519, at = {1438, 38.32, 34.36}, z = 1324.5, chain = "ps-teld-s054-3519", text = "Entrega a Arynia.", status = "unverified" },
    { id = "ps-teld-176", ["do"] = "accept", quest = 98392, npc = 3519, at = {1438, 38.32, 34.36}, z = 1324.5, chain = "ps-teld-s054-3519", text = "Coge la continuación (nueva de Forever): tres arpías con nombre.", status = "unverified", reqlevel = 6 },
    { id = "ps-teld-177", ["do"] = "complete", quest = 98392, obj = 1, at = {1438, 35.05, 39.29}, text = "Consigue {item:280831} (1) de {npc:272034} para «{quest:98392}».", tip = "Limpia alrededor antes de atacar a cada una. Arysa, al norte, es la más dura. {npc:272034} y {npc:272044} vuelan justo al oeste del pozo de la luna, {npc:272046} más al norte.", status = "unverified" },
    { id = "ps-teld-178", ["do"] = "complete", quest = 98392, obj = 2, at = {1438, 33.18, 36.13}, text = "Consigue {item:280832} (1) de {npc:272044} para «{quest:98392}».", status = "unverified" },
    { id = "ps-teld-179", ["do"] = "complete", quest = 98392, obj = 3, at = {1438, 34.22, 27.94}, text = "Consigue {item:280834} (1) de {npc:272046} para «{quest:98392}».", status = "unverified" },
    { id = "ps-teld-180", ["do"] = "accept", quest = 931, at = {1438, 34.61, 28.76}, z = 1327.6, text = "Al norte, examina la planta de frondas extrañas: misión para Denalan.", tip = "[EN] The {obj:6752} grows at the glade's north end, on the way: then north of {npc:272046}, along the island's northern edge by Wellspring Lake, {npc:7319}, a level 12 spider, lurks.", status = "unverified", reqlevel = 4 },
    { id = "ps-teld-181", ["do"] = "complete", quest = 2518, obj = 1, at = {1438, 39.4, 25.4}, wps = {{1438, 41.5, 25.4, "Espineretas de plata"}, {1438, 46.2, 24.4, "Espineretas de plata"}, {1438, 48.1, 25.5, "Espineretas de plata"}}, text = "Consigue {item:8344} (1) de {npc:7319} para «{quest:2518}».", tip = "Patrulla entre los árboles del norte. Si hay otros jugadores, espera a que reaparezca.", status = "unverified" },
    { id = "ps-teld-182", ["do"] = "turnin", quest = 98392, npc = 3519, at = {1438, 38.32, 34.36}, z = 1324.5, chain = "ps-teld-s057-3519", text = "Entrega los amuletos a Arynia.", status = "unverified" },
    { id = "ps-teld-183", ["do"] = "accept", quest = 98398, npc = 3519, at = {1438, 38.32, 34.36}, z = 1324.5, chain = "ps-teld-s057-3519", text = "Coge la misión del Árbol del Oráculo.", status = "unverified", reqlevel = 6 },
    { id = "ps-teld-184", ["do"] = "turnin", quest = 98398, at = {1438, 36.97, 34.04}, text = "Toca la corteza del Árbol del Oráculo, junto a la poza.", tip = "{obj:673378}, justo al oeste del pozo de la luna.", status = "unverified" },
    { id = "ps-teld-185", ["do"] = "accept", quest = 940, at = {1438, 36.97, 34.04}, text = "Coge de la corteza la misión para el Archidruida Fandral Staghelm.", tip = "[EN] The same {obj:673378}: Fandral in {map:1457} takes it.", status = "unverified", reqlevel = 6 },
    { id = "ps-teld-186", ["do"] = "turnin", quest = 490, npc = 2155, at = {1438, 42.22, 51.27}, z = 1325.0, text = "Vuelve al camino y entrega los colmillos a Shayla.", tip = "Al sur desde el claro hacia Ursal: Shayla recorre el camino al oeste de Dolanaar, desde donde lo cruza el sendero que baja del claro, al suroeste hasta la curva en torno a 38,54, y vuelta.", status = "unverified" },
    { id = "ps-teld-187", ["do"] = "complete", quest = 486, obj = 1, at = {1438, 38.83, 79.81}, z = 1328.1, text = "Mata {npc:2039} (1) para «{quest:486}».", tip = "[EN] Walk south along the west side of the island. Ursal prowls the far south, below the Pozas de Arlithrien.\nCareful: Gnarlpine of roughly level 9-12 crowd the camp and sit close together, so it is easy to pull several at once. Take them on singly before you engage Ursal.", status = "unverified" },
    { id = "ps-teld-188", ["do"] = "turnin", quest = 99047, npc = 6094, at = {1438, 55.29, 56.82}, z = 1313.9, chain = "ps-teld-s060-6094", text = "Entrega la misión de Eralya a Byancie.", tip = "Al noreste desde la guarida de Ursal, de vuelta a Dolanaar. [EN] {npc:6094}, inside.", status = "unverified" },
    { id = "ps-teld-189", ["do"] = "accept", quest = 99050, npc = 6094, at = {1438, 55.29, 56.82}, z = 1313.9, chain = "ps-teld-s060-6094", text = "Coge la misión de Byancie (nueva de Forever): frondas, vial y agua.", status = "unverified", reqlevel = 4 },
    { id = "ps-teld-190", ["do"] = "buy", npc = 3614, item = 3371, count = 1, at = {1438, 55.27, 57.15}, z = 1328.0, text = "Compra {item:3371} a {npc:3614}.", tip = "{item:3371} de {npc:3614}, junto a {npc:6094}.", status = "unverified" },
    { id = "ps-teld-191", ["do"] = "turnin", quest = 486, npc = 2078, at = {1438, 55.96, 57.27}, z = 1313.9, text = "Entrega a Athridas.", status = "unverified" },
    { id = "ps-teld-192", ["do"] = "note", npc = 3602, at = {1438, 55.95, 61.56}, z = 1293.8, text = "Entrena tus hechizos de clase con {npc:3602}.", status = "unverified" },
    { id = "ps-teld-193", ["do"] = "buy", npc = 6736, item = 159, count = 1, at = {1438, 55.62, 59.79}, z = 1314.0, text = "Compra {item:159} al {npc:6736}.", tip = "{item:159} de {npc:6736}, para {npc:6094}.", status = "unverified" },
    { id = "ps-teld-194", ["do"] = "turnin", quest = 7383, npc = 3515, at = {1438, 56.14, 61.71}, z = 1294.2, chain = "ps-teld-s060-3515", text = "Entrega la redoma de amatista a Corithras.", status = "unverified" },
    { id = "ps-teld-195", ["do"] = "accept", quest = 935, npc = 3515, at = {1438, 56.14, 61.71}, z = 1294.2, chain = "ps-teld-s060-3515", text = "Coge la última Corona de la Tierra: para Fandral, en Darnassus.", tip = "La recibe Fandral en {map:1457}.", status = "unverified" },
    { id = "ps-teld-196", ["do"] = "accept", quest = 5925, npc = 3602, at = {1438, 55.95, 61.56}, z = 1293.8, ["if"] = { class = {"DRUID"} }, text = "Coge con Kal la misión que te manda al Enclave Cenarion de Darnassus.", tip = "Si estás ya en Darnassus, Denatharion da la misma misión en el Enclave Cenarion.", status = "unverified", reqlevel = 10 },
    { id = "ps-teld-197", ["do"] = "turnin", quest = 98403, npc = 3567, at = {1438, 55.57, 56.95}, z = 1354.9, optional = true, text = "Entrega a Tallonkai.", tip = "Vuelve arriba con {npc:3567} con las arañas hechas y el musgo de {npc:272116}. [EN] {npc:3567}, upstairs.", status = "unverified" },
    { id = "ps-teld-198", ["do"] = "turnin", quest = 930, npc = 2080, at = {1438, 60.9, 68.49}, z = 1255.9, chain = "ps-teld-s062-2080", text = "Entrega el fruto extraño a Denalan.", tip = "Al sureste de Dolanaar, hasta {npc:2080}. Los brotes azotadores deambulan a su alrededor en la orilla.", status = "unverified" },
    { id = "ps-teld-199", ["do"] = "turnin", quest = 931, npc = 2080, at = {1438, 60.9, 68.49}, z = 1255.9, chain = "ps-teld-s062-2080", text = "Entrega la fronda extraña a Denalan.", status = "unverified" },
    { id = "ps-teld-200", ["do"] = "turnin", quest = 2399, at = {1438, 60.75, 68.56}, z = 1255.9, text = "Completa las frondas brotadas en la maceta de Denalan.", status = "unverified" },
    { id = "ps-teld-201", ["do"] = "complete", quest = 99050, obj = 1, at = {1438, 62.07, 68.84}, wps = {{1438, 61.0, 69.3, "Fronda húmeda de azotadora"}, {1438, 57.8, 71.2, "Fronda húmeda de azotadora"}, {1438, 57.6, 66.0, "Fronda húmeda de azotadora"}}, text = "Consigue {item:286017} (6) para «{quest:99050}».", status = "unverified" },
    { id = "ps-teld-202", ["do"] = "turnin", quest = 99050, npc = 6094, at = {1438, 55.29, 56.82}, z = 1313.9, chain = "ps-teld-s063-6094", text = "Vuelve a Dolanaar y entrega a Byancie.", tip = "[EN] {npc:6094} takes a {item:159} with the fronds and the vial: if you drank yours, buy another from {npc:6736} in this inn before you hand in. [EN] {npc:6094}, inside.", status = "unverified" },
    { id = "ps-teld-203", ["do"] = "accept", quest = 99073, npc = 6094, at = {1438, 55.29, 56.82}, z = 1313.9, chain = "ps-teld-s063-6094", text = "Coge su siguiente misión: llévale el remedio a Eralya.", status = "unverified", reqlevel = 4 },
